@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_available_commands_is_packet_76(version):
    assert version.PACKETS[76] is version.AvailableCommandsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_available_commands_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_available_commands_decodes_from_its_golden(packet, golden):
    assert v2225.AvailableCommandsPacket.from_bytes(golden) == packet
